#!/usr/bin/env bash
# Auto-generated by training/setup_peft_compare.py
# Sequentially trains PEFT-comparison runs (BitFit / IA3 / full FT).
# RESUMABLE: each cell skips if its trained artifact already exists. Safe
# to kill and restart (mirrors run_peft_compare_full_sweep.sh:skip_if_done).
set -e
cd "$(dirname "$0")/.."
echo "PEFT comparison sweep starting:" $(date)

skip_if_done() {
  local rn="$1"; local m="$2"
  if [[ "$m" == "full" || "$m" == "bitfit" ]]; then
    [[ -s "checkpoints/${rn}/best.pt" ]]
  else
    [[ -s "checkpoints/${rn}/adapter/adapter_config.json" && -s "checkpoints/${rn}/embedding_extension.pt" ]]
  fi
}

run_cell() {
  local idx="$1"; local rn="$2"; local m="$3"; local cfg="$4"
  echo "[${idx}/7] ${cfg}"
  if skip_if_done "$rn" "$m"; then
    echo "    SKIP — checkpoint exists at checkpoints/${rn}"
  else
    UV_CACHE_DIR=/tmp/uv-cache uv run python training/lora_train.py --config "$cfg"
  fi
}

run_cell 1 ft_f1_bitfit_classical bitfit training/configs/lora/peft_compare/classical_bitfit.yaml
run_cell 2 ft_f1_ia3_classical    ia3    training/configs/lora/peft_compare/classical_ia3.yaml
run_cell 3 ft_f1_bitfit_country   bitfit training/configs/lora/peft_compare/country_bitfit.yaml
run_cell 4 ft_f1_ia3_country      ia3    training/configs/lora/peft_compare/country_ia3.yaml
run_cell 5 ft_f1_full_ft_country  full   training/configs/lora/peft_compare/country_full.yaml
run_cell 6 ft_f1_bitfit_rock      bitfit training/configs/lora/peft_compare/rock_bitfit.yaml
run_cell 7 ft_f1_ia3_rock         ia3    training/configs/lora/peft_compare/rock_ia3.yaml

echo 'PEFT comparison sweep finished' $(date)
